# ============================================================
# Lib/build_dynamic.ps1 — 动态库 FFI 绑定生成器 (Windows PowerShell)
#
# 从用户 C 源码编译 .dll，调用 GenDyn v2 工具
# 自动生成 C 胶水代码 + VML 封装 + 22 语言 FFI 头文件。
#
# 用法:
#   .\build_dynamic.ps1 myui.c                    # 编译+生成所有 FFI 绑定
#   .\build_dynamic.ps1 myui.c -OutputName libgfx # 指定输出库名
#   .\build_dynamic.ps1 myui.c -LangOnly          # 仅生成语言头文件
#   .\build_dynamic.ps1 myui.h -Dll libmyui.dll   # 从已有头文件+动态库生成
#
# 示例 (myui.c):
#   int setpoint(int x, int y, int co) { return 0; }
#   void clear_screen(int color) { }
#
# 生成文件 (由 GenDyn v2 生成):
#   Lib/dynamic/<libname>.vml                  — VML FFI 封装
#   Lib/<lang>/ext/lib<libname>.<ext>          — 22 语言绑定
#
# 相关工具:
#   GenDyn (tools/GenDyn) — 外部动态库 FFI 绑定生成
# ============================================================
param(
    [Parameter(Position=0)][string]$InFile = "",
    [string]$OutputName = "",
    [string]$Dll = "",
    [switch]$LangOnly,
    [switch]$Help
)

$ErrorActionPreference = "Stop"

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$ProjectRoot = Split-Path -Parent $ScriptDir

# 自动检测工具: tools/ → tools/bin/ → 源码编译发布到 tools/bin/
$GenDynBin = ""
$GenDynProj = ""
$toolsDir = "$ScriptDir\..\tools"
$toolsBinDir = "$toolsDir\bin"
if (Test-Path "$toolsDir\gendyn.exe" -PathType Leaf) {
    $GenDynBin = "$toolsDir\gendyn.exe"
} elseif (Test-Path "$toolsDir\gendyn" -PathType Leaf) {
    $GenDynBin = "$toolsDir\gendyn"
} elseif (Test-Path "$toolsBinDir\gendyn.exe" -PathType Leaf) {
    $GenDynBin = "$toolsBinDir\gendyn.exe"
} elseif (Test-Path "$toolsBinDir\gendyn" -PathType Leaf) {
    $GenDynBin = "$toolsBinDir\gendyn"
} elseif (Test-Path "$toolsBinDir\GenDyn.exe" -PathType Leaf) {
    $GenDynBin = "$toolsBinDir\GenDyn.exe"
} elseif (Test-Path "$toolsBinDir\GenDyn" -PathType Leaf) {
    $GenDynBin = "$toolsBinDir\GenDyn"
} elseif (Test-Path "$ProjectRoot\tools\GenDyn") { $GenDynProj = "$ProjectRoot\tools\GenDyn" }
else { Write-Fail "找不到 gendyn (发布目录或源码项目)"; exit 1 }

$needPublish = $false
if (-not $GenDynBin -and $GenDynProj) { $needPublish = $true }

function Invoke-GenDyn([string[]]$Args) {
    if ($needPublish) {
        Write-Info "首次使用，正在编译发布 GenDyn → tools/bin/ ..."
        New-Item -ItemType Directory -Path $toolsBinDir -Force | Out-Null
        dotnet publish $GenDynProj -c Release -o $toolsBinDir 2>&1
        if ($LASTEXITCODE -ne 0) { Write-Fail "编译发布失败"; exit 1 }
        Write-Pass "GenDyn 发布完成"
        # 查找可执行文件: 短名称 → 程序集名
        if (Test-Path "$toolsBinDir\gendyn.exe" -PathType Leaf) { $GenDynBin = "$toolsBinDir\gendyn.exe" }
        elseif (Test-Path "$toolsBinDir\gendyn" -PathType Leaf) { $GenDynBin = "$toolsBinDir\gendyn" }
        elseif (Test-Path "$toolsBinDir\GenDyn.exe" -PathType Leaf) { $GenDynBin = "$toolsBinDir\GenDyn.exe" }
        elseif (Test-Path "$toolsBinDir\GenDyn" -PathType Leaf) { $GenDynBin = "$toolsBinDir\GenDyn" }
        if (-not $GenDynBin) { Write-Fail "找不到编译产物: $toolsBinDir\gendyn 或 $toolsBinDir\GenDyn"; exit 1 }
        $needPublish = $false
    }
    if ($GenDynBin) {
        & $GenDynBin $Args 2>&1
    } else {
        dotnet run --project $GenDynProj -- $Args 2>&1
    }
}

function Write-Info  { Write-Host "[..] $args" -ForegroundColor Yellow }
function Write-Pass  { Write-Host "[OK] $args" -ForegroundColor Green }
function Write-Fail  { Write-Host "[!!] $args" -ForegroundColor Red }

if ($Help -or [string]::IsNullOrEmpty($InFile)) {
    Write-Host "build_dynamic.ps1 — 用户 C 源码 → 动态库 + 16 语言 FFI 绑定"
    Write-Host "用法: .\build_dynamic.ps1 <file.c|file.h> [-OutputName <name>] [-Dll <dll>] [-LangOnly]"
    Write-Host ""
    Write-Host "内部调用 GenDyn v2 工具生成:"
    Write-Host "  VML 封装 (Lib/dynamic/<name>.vml) + 22 语言绑定 (Lib/<lang>/ext/lib<name>.<ext>)"
    Write-Host ""
    Write-Host "要求: Visual Studio (cl.exe) 或 MinGW (gcc) 用于编译 C 源码"
    Write-Host ""
    Write-Host "相关工具:"
    Write-Host "  GenDyn   外部动态库 FFI 绑定生成 (本脚本的后端)"
    Write-Host "  GenLib         VML 标准共享库管理"
    exit 0
}

if (-not (Test-Path $InFile)) { Write-Fail "文件不存在: $InFile"; exit 1 }

$ext = [System.IO.Path]::GetExtension($InFile) -replace '^\.', ''
if ([string]::IsNullOrEmpty($OutputName)) {
    $OutputName = [System.IO.Path]::GetFileNameWithoutExtension($InFile)
}

# ============================================================
# 从 C 源码提取函数声明为头文件
# ============================================================
function Extract-Header([string]$CFile, [string]$OutHeader) {
    $content = Get-Content $CFile -Raw
    $pattern = '(?m)^\s*(void|int|char|short|long|float|double|unsigned)\s+[_*a-zA-Z][_a-zA-Z0-9]*\s*\('
    $lines = [regex]::Matches($content, "$pattern.*") | ForEach-Object {
        ($_.Value -replace '\s*\{.*', '') -replace '^\s*', '' -replace ';*$', ';'
    }
    $sb = @()
    $sb += "/* Auto-generated by build_dynamic — extracted from $CFile */"
    foreach ($line in $lines) {
        if ($line -match '^\s*//') { continue }
        # 提取函数名用于过滤关键字
        $funcMatch = [regex]::Match($line, '(\w+)\s*\(')
        $funcName = if ($funcMatch.Success) { $funcMatch.Groups[1].Value } else { '' }
        $keywords = @('if','while','for','return','switch','case','sizeof','main')
        if ($funcName -in $keywords) { continue }
        $sb += "extern $line"
    }
    $sb += ""
    $sb | Out-File -FilePath $OutHeader -Encoding ascii
}

# ============================================================
# 查找 C 编译器
# ============================================================
function Find-Compiler {
    # 优先 MSVC cl.exe (通过 vswhere)
    try {
        $vsWhere = "${env:ProgramFiles(x86)}\Microsoft Visual Studio\Installer\vswhere.exe"
        if (Test-Path $vsWhere) {
            $vsPath = & $vsWhere -latest -products * -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath 2>$null
            if ($vsPath) {
                $vcVars = "$vsPath\VC\Auxiliary\Build\vcvars64.bat"
                if (Test-Path $vcVars) { return @('msvc', $vcVars) }
            }
        }
    } catch {}
    # 回退: 查找 cl.exe 是否在 PATH 中
    $clPath = (Get-Command cl.exe -ErrorAction SilentlyContinue).Source
    if ($clPath) { return @('msvc-direct', $clPath) }
    # 回退: MinGW gcc
    $gccPath = (Get-Command gcc.exe -ErrorAction SilentlyContinue).Source
    if ($gccPath) { return @('gcc', $gccPath) }
    return $null
}

# ============================================================
# 编译 C → DLL
# ============================================================
function Compile-Dll([string]$CFile, [string]$OutDll) {
    $compiler = Find-Compiler
    if (-not $compiler) {
        Write-Fail "未找到 C 编译器。请安装 Visual Studio 或 MinGW。"
        Write-Fail "Visual Studio: https://visualstudio.microsoft.com/"
        Write-Fail "MinGW: https://www.mingw-w64.org/"
        return $false
    }
    $type = $compiler[0]
    Write-Info "编译器: $type"

    if ($type -eq 'msvc') {
        $vcVars = $compiler[1]
        $outDir = Split-Path -Parent $OutDll
        $baseName = [System.IO.Path]::GetFileNameWithoutExtension($OutDll)
        $batch = @"
@echo off
call "$vcVars" >nul 2>&1
cl /nologo /O2 /MD /LD /Fe"$OutDll" "$CFile" >nul 2>&1
exit %ERRORLEVEL%
"@
        $batchFile = "$env:TEMP\build_dynamic_compile.bat"
        $batch | Out-File -FilePath $batchFile -Encoding ascii
        $result = cmd /c $batchFile 2>&1
        Remove-Item $batchFile -Force -ErrorAction SilentlyContinue
        if ($LASTEXITCODE -ne 0) {
            Write-Fail "MSVC 编译失败"
            Write-Host $result
            return $false
        }
    } elseif ($type -eq 'msvc-direct') {
        $result = cmd /c "cl /nologo /O2 /MD /LD /Fe`"$OutDll`" `"$CFile`" 2>&1"
        if ($LASTEXITCODE -ne 0) {
            Write-Fail "MSVC 编译失败"
            Write-Host $result
            return $false
        }
    } elseif ($type -eq 'gcc') {
        $result = cmd /c "gcc -shared -fPIC -o `"$OutDll`" `"$CFile`" 2>&1"
        if ($LASTEXITCODE -ne 0) {
            Write-Fail "GCC 编译失败"
            Write-Host $result
            return $false
        }
    }
    return $true
}

# ============================================================
# 主流程
# ============================================================

Set-Location $ScriptDir

if ($ext -eq 'c') {
    $header = "$env:TEMP\build_dynamic_${OutputName}.h"
    Write-Info "提取函数声明: $InFile → $header"
    Extract-Header $InFile $header

    $dllFile = "$ScriptDir\${OutputName}.dll"
    Write-Info "编译动态库: $InFile → $dllFile"
    if (-not (Compile-Dll $InFile $dllFile)) {
        Write-Fail "动态库编译失败"
        exit 1
    }
    Write-Pass $dllFile

    Write-Info "调用 GenDyn v2 生成 FFI 绑定..."
    if ($LangOnly) {
        $genDynArgs = @('-g', '-n', $OutputName, '-H', $header, '-r', $ProjectRoot)
    } else {
        $genDynArgs = @('-A', '-n', $OutputName, '-H', $header, '-r', $ProjectRoot)
    }
    $result = Invoke-GenDyn $genDynArgs
    if ($LASTEXITCODE -ne 0) {
        Write-Host $result
        Write-Fail "GenDyn 执行失败"
        exit 1
    }
    Write-Pass "GenDyn 完成"

    # 清理临时头文件
    Remove-Item $header -Force -ErrorAction SilentlyContinue

    Write-Host ""
    Write-Host "===== 完成 ====="
    Write-Host "动态库:     $dllFile"
    Write-Host "VML 封装:   Lib/dynamic/${OutputName}.vml"
    Write-Host "各语言 FFI: Lib/<lang>/ext/lib${OutputName}.<ext>"
    Write-Host ""
    Write-Host "下一步:"
    Write-Host "  1. 将 $dllFile 放入 Lib/dynamic/"
    Write-Host "  2. 在 VML 程序中: .linked  `"Lib/dynamic/${OutputName}.vml`""

} elseif ($ext -eq 'h') {
    if ([string]::IsNullOrEmpty($Dll)) {
        Write-Fail "头文件模式需要指定动态库路径: -Dll <lib.dll>"
        exit 1
    }
    if (-not (Test-Path $Dll)) { Write-Fail "动态库不存在: $Dll"; exit 1 }

    Write-Info "调用 GenDyn v2 (头文件模式)..."
    if ($LangOnly) {
        $genDynArgs = @('-g', '-n', $OutputName, '-H', "$InFile", '-r', $ProjectRoot)
    } else {
        $genDynArgs = @('-A', '-n', $OutputName, '-H', "$InFile", '-r', $ProjectRoot)
    }
    $result = Invoke-GenDyn $genDynArgs
    if ($LASTEXITCODE -ne 0) {
        Write-Host $result
        Write-Fail "GenDyn 执行失败"
        exit 1
    }
    Write-Pass "GenDyn 完成"
    Write-Host ""
    Write-Host "===== 完成 ====="
    Write-Host "各语言 FFI: <lang>/ext/$OutputName.<ext>"
} else {
    Write-Fail "不支持的文件类型: .$ext (需要 .c 或 .h)"
    exit 1
}
